};

/**
 * Load and merge config. User settings override defaults field-by-field
 * (arrays are replaced, not concatenated, to match standard JSON-config
 * expectations — user opts in to the full list they want).
 *
 * `tool_search` and provider-native web tools are always force-added to
 * `alwaysActive` regardless of user config. Goal-control tools are handled at
 * session_start from the current pi-goal state so ordinary sessions do not pay
 * their schemas.
 */
const FORCE_ALWAYS_ACTIVE = [
  "tool_search",
  // 2026-05-28: web_fetch/web_search removed from forced-always-active.
  // claude-bridge still injects them as provider-native server tools, so the
  // model can call them; we just no longer pin the schemas in the Pi tools[]
  // and the capital-W native-tool-overrides WebFetch/WebSearch can defer
  // cleanly. Net effect: no eager schema billing, fewer mid-session swaps.
  //
  // 2026-06-10: WebFetch/WebSearch (CC Title-Case names from pi-claude-conversion)
  // are provider-native bridge tools. They must NOT appear in the BM25 deferred
  // index — if tool_search indexed them, a "select:WebFetch" query could try to
  // treat them as standard function tools rather than letting the bridge intercept
  // them natively. Force-always-active means tool-search skips cataloging them;
  // they remain in tools[] as deferLoading:true stubs (zero eager schema cost)
  // and are callable directly. Matches the treatment of web_fetch/web_search.
  "WebFetch",
  "WebSearch",
];

export function loadConfig(): ToolSearchConfig {
  const path = join(process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent"), "settings.json");
  let userPart: Partial<ToolSearchConfig> = {};
  try {
    const raw = readFileSync(path, "utf8");
    const parsed = JSON.parse(raw) as { extensions?: { "pi-tool-search"?: Partial<ToolSearchConfig> } };
    userPart = parsed.extensions?.["pi-tool-search"] ?? {};
  } catch {
    // No settings.json or unreadable — fall back to defaults silently.
  }

  const merged: ToolSearchConfig = {
    deferByDefault: userPart.deferByDefault ?? DEFAULTS.deferByDefault,
    defer: userPart.defer ?? DEFAULTS.defer,

