/**
 * Config loader for pi-tool-search.
 *
 * Reads `~/.pi/agent/settings.json` → `extensions.pi-tool-search.*` and
 * falls back to package defaults. Config is read once per session_start
 * (cached in-process); the user can change it and the next pi reload
 * picks it up.
 *
 * Schema (all fields optional):
 *
 *   {
 *     "extensions": {
 *       "pi-tool-search": {
 *         "defer":              string[]       // tool names to hide behind tool_search
 *         "alwaysActive":       string[]       // tool names that must never defer
 *         "rememberDiscovered": boolean        // persist discovered set via custom entries
 *         "showDeferredHints":  boolean        // render <deferred-tools> names block in prompt
 *       }
 *     }
 *   }
 */
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

export interface ToolSearchConfig {
  /**
   * Defer-by-default posture (matches Claude Code & Codex industry standard).
   * When true: every tool not in `alwaysActive` is deferred; `defer` is ignored.
   * When false: only tools listed in `defer` are deferred (legacy opt-in mode).
   */
  deferByDefault: boolean;
  /** Tool names to defer (only used when deferByDefault === false). */
  defer: string[];
  /** Tool names that must always stay active (never defer). */
  alwaysActive: string[];
  /** Persist discovered-tool set across resume/fork via custom session entries. */
  rememberDiscovered: boolean;
  /** Render `<deferred-tools>` names block in the system prompt so the model knows what's available. */
  showDeferredHints: boolean;
}

/**
 * Default deferral list — derived from PLAN.md decisions Q4 + Q5.
 *
 * Computer-use cluster: heavy/situational, not used in pure-coding sessions.
 * Chat cluster: pi-chat-specific, only useful in chat-mode sessions.
 * Subagent + intercom: situational orchestration tools.
 * Autoresearch trio: only used in autoresearch sessions.
 * Context manipulation: situational, used in long sessions.
 */
const DEFAULT_DEFER = [
  // computer-use cluster (Q4)
  "arrange_window",
  "click",
  "computer_actions",
  "double_click",
  "drag",
  "keypress",
  "list_apps",
  "list_windows",
  "move_mouse",
  "screenshot",
  "scroll",
  "set_text",
  "type_text",
  "wait",
  // chat cluster (Q5)
  "chat_attach",
  "chat_history",
  "chat_request_secret",
  // orchestration
  "subagent",
  "intercom",
  // autoresearch
  "init_experiment",
  "log_experiment",
  "run_experiment",
  // context manipulation
  "context_checkout",
  "context_log",
  "context_tag",
];

/**
 * Default always-active list — mirrors Claude Code's keep-active set
 * (Bash/Read/Edit/Write/Grep/Glob/AgentTool/Skill/ToolSearch) plus Pi's
 * core: `skill_search` and `memory_note`.
 *
 * CACHE CRITICAL: keep one spelling per capability here. Listing both
 * lowercase and Claude-style aliases makes both schemas sticky in tools[] and
 * defeats tool_search deferral.
 *
 * `Find`, `Ls`, `TaskStop`, and `TaskList` are intentionally
 * omitted: native-tool-aliases registers them with `deferLoading: true`, so
 * they stay provider-visible on Anthropic without eager full-schema billing.
 * TaskOutput is intentionally not exposed; background output is push-notified
 * and inspected through Read on returned output file paths.
 */
// Agent removed 2026-05-28: defer it and let tool_search summon it on demand.
// NOTE (2026-06-08): the old "~140k tokens/session" rationale here was wrong by
// ~90x. The Agent tool's billed footprint is ~2.5k tok (params ~1.5k +
// description ~0.1k + promptGuidelines ~1k), measured from the built fork. As a
// defer_loading stub it bills ~0 until summoned; pinning it always-active costs
// only ~2.5k, not 140k. Deferral is still correct (keeps the eager set lean and
// the prompt focused), but do not justify it with the bogus 140k figure.
const DEFAULT_ALWAYS_ACTIVE = [
  "Bash",
  "Read",
  "Edit",
  "Write",
  "Grep",
  "skill",
  "skill_search",
  "tool_search",
  "memory_note",
];

const DEFAULTS: ToolSearchConfig = {
  deferByDefault: true,
  defer: DEFAULT_DEFER,
  alwaysActive: DEFAULT_ALWAYS_ACTIVE,
  rememberDiscovered: true,
  showDeferredHints: true,
};

/**
 * Load and merge config. User settings override defaults field-by-field
 * (arrays are replaced, not concatenated, to match standard JSON-config
 * expectations — user opts in to the full list they want).
 *
 * `tool_search` and provider-native web tools are always force-added to
 * `alwaysActive` regardless of user config. Goal-control tools are handled at
 * session_start from the current pi-goal state so ordinary sessions do not pay
 * their schemas.
 */
const FORCE_ALWAYS_ACTIVE = [
  "tool_search",
  // 2026-05-28: web_fetch/web_search removed from forced-always-active.
  // claude-bridge still injects them as provider-native server tools, so the
  // model can call them; we just no longer pin the schemas in the Pi tools[]
  // and the capital-W native-tool-overrides WebFetch/WebSearch can defer
  // cleanly. Net effect: no eager schema billing, fewer mid-session swaps.
  //
  // 2026-06-10: WebFetch/WebSearch (CC Title-Case names from pi-claude-conversion)
  // are provider-native bridge tools. They must NOT appear in the BM25 deferred
  // index — if tool_search indexed them, a "select:WebFetch" query could try to
  // treat them as standard function tools rather than letting the bridge intercept
  // them natively. Force-always-active means tool-search skips cataloging them;
  // they remain in tools[] as deferLoading:true stubs (zero eager schema cost)
  // and are callable directly. Matches the treatment of web_fetch/web_search.
  "WebFetch",
  "WebSearch",
];

export function loadConfig(): ToolSearchConfig {
  const path = join(process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent"), "settings.json");
  let userPart: Partial<ToolSearchConfig> = {};
  try {
    const raw = readFileSync(path, "utf8");
    const parsed = JSON.parse(raw) as { extensions?: { "pi-tool-search"?: Partial<ToolSearchConfig> } };
    userPart = parsed.extensions?.["pi-tool-search"] ?? {};
  } catch {
    // No settings.json or unreadable — fall back to defaults silently.
  }

  const merged: ToolSearchConfig = {
    deferByDefault: userPart.deferByDefault ?? DEFAULTS.deferByDefault,
    defer: userPart.defer ?? DEFAULTS.defer,
    alwaysActive: userPart.alwaysActive ?? DEFAULTS.alwaysActive,
    rememberDiscovered: userPart.rememberDiscovered ?? DEFAULTS.rememberDiscovered,
    showDeferredHints: userPart.showDeferredHints ?? DEFAULTS.showDeferredHints,
  };

  // Force critical control tools into alwaysActive — non-negotiable.
  for (const toolName of FORCE_ALWAYS_ACTIVE) {
    if (!merged.alwaysActive.includes(toolName)) {
      merged.alwaysActive = [...merged.alwaysActive, toolName];
    }
  }

  return merged;
}

/**
 * Catalog of deferred tools.
 *
 * At session_start we ask pi for every registered tool, filter to the
 * configured `defer` list, and snapshot enough metadata for the
 * `tool_search` tool to rank queries against.
 *
 * This is our local mirror — pi's own registry is canonical, we just keep
 * the search-relevant bits handy. Once a tool is discovered (`select:foo`
 * or matching keyword search), we re-add it to pi's active set; the model
 * then picks up the full schema from the tools list on the next turn.
 */
import type { ExtensionAPI } from "@valkyriweb/pi-coding-agent";

interface RegisteredTool {
  name: string;
  description?: string;
  deferLoading?: boolean;
}

const TOOL_CAPABILITY_KEYS = new Map<string, string>([
  ["bash", "bash"],
  ["bash_output", "bash_output"],
  ["bashoutput", "bash_output"],
  ["bash_kill", "bash_kill"],
  ["killshell", "bash_kill"],
  ["agent", "agent"],
  ["task", "agent"],
  ["read", "read"],
  ["edit", "edit"],
  ["write", "write"],
  ["grep", "grep"],
  ["find", "find"],
  ["ls", "ls"],
  ["webfetch", "web_fetch"],
  ["web_fetch", "web_fetch"],
  ["websearch", "web_search"],
  ["web_search", "web_search"],
]);

// Preferred registry name per capability when duplicate variants exist. Native
// file/shell tools use upstream lowercase names; Agent and the Task* job-control
// tools keep their CC-canonical casing (no lowercase form).
const PREFERRED_TOOL_NAMES = new Map<string, string>([
  ["bash", "bash"],
  ["bash_output", "BashOutput"],
  ["bash_kill", "KillShell"],
  ["agent", "Agent"],
  ["read", "read"],
  ["edit", "edit"],
  ["write", "write"],
  ["grep", "grep"],
  ["find", "find"],
  ["ls", "ls"],
  ["web_fetch", "web_fetch"],
  ["web_search", "web_search"],
]);

export interface CatalogEntry {
  name: string;
  description: string;
  /** Whether the provider can receive this tool as a native deferred schema. */
  deferLoading: boolean;
  /** Tokenised lowercase blob of name + description for substring scoring. */
  searchBlob: string;
}

/**
 * Normalize tool names by capability for config matching. Pi may expose both
 * Claude-style aliases (`Bash`) and legacy/internal names (`bash`); user config
 * should match the capability without double-billing every spelling.
 */
export function normalizeToolName(name: unknown): string {
  if (typeof name !== "string") return "";
  const trimmedName = name.trim();
  if (trimmedName.length === 0) return "";
  const localName = trimmedName.startsWith("mcp__pi__") ? trimmedName.slice("mcp__pi__".length) : trimmedName;
  const lowered = localName.toLowerCase();
  return TOOL_CAPABILITY_KEYS.get(lowered) ?? lowered;
}

export function hasToolName(names: ReadonlySet<string>, name: unknown): boolean {
  if (typeof name === "string" && names.has(name)) return true;
  const key = normalizeToolName(name);
  if (key.length === 0) return false;
  if (names.has(key)) return true;
  for (const candidate of names) {
    if (normalizeToolName(candidate) === key) return true;
  }
  return false;
}

function normalizeToolNames(names: ReadonlySet<string>): Set<string> {
  return new Set([...names].map(normalizeToolName).filter(Boolean));
}

function getRegisteredTools(pi: ExtensionAPI): RegisteredTool[] {
  return pi.tools.definitions();
}

function isPreferredVariant(tool: RegisteredTool, availableNames: ReadonlySet<string>): boolean {
  const preferred = PREFERRED_TOOL_NAMES.get(normalizeToolName(tool.name));
  if (!preferred || tool.name === preferred) return true;
  return !availableNames.has(preferred);
}

/**
 * Build the catalog from pi's read-only tool registry snapshot.
 *
 * Only tools whose names appear in `deferNames` (and not in `alwaysActive`)
 * make it in. Anything in `deferNames` that doesn't actually exist as a
 * registered tool is silently skipped — extensions come and go, we don't
 * want to crash on stale config.
 *
 * CACHE CRITICAL: this catalog is rendered into the prompt. Do not include
 * tools that are already active, and keep name matching stable/case-safe so
 * aliases do not appear in both tools[] and <deferred-tools>.
 */
export function buildCatalog(
  pi: ExtensionAPI,
  deferNames: ReadonlySet<string>,
  alwaysActive: ReadonlySet<string>,
  deferByDefault = false,
): CatalogEntry[] {
  const all = getRegisteredTools(pi);
  const availableNames = new Set(all.map((tool) => tool.name));
  const normalizedDefer = normalizeToolNames(deferNames);
  const normalizedAlwaysActive = normalizeToolNames(alwaysActive);
  const out: CatalogEntry[] = [];
  for (const tool of all) {
    if (!isPreferredVariant(tool, availableNames)) continue;
    if (hasToolName(normalizedAlwaysActive, tool.name)) continue;
    if (!deferByDefault && !hasToolName(normalizedDefer, tool.name)) continue;
    out.push({
      name: tool.name,
      description: tool.description ?? "",
      deferLoading: tool.deferLoading === true,
      searchBlob: `${tool.name} ${tool.description ?? ""}`.toLowerCase(),
    });
  }
  return out;
}

/**
 * Compute the active-tool list for the current session.
 *
 * Final active set = (every registered tool) − (deferred set ∩ catalog) + previouslyDiscovered.
 *
 * `alwaysActive` overrides `defer` — anything in alwaysActive stays even if
 * also listed in defer (defensive: protects load-bearing tools from a
 * config typo).
 */
export type DeferredToolMode = "none" | "anthropic_tool_reference" | "openai_codex_defer_loading";

function keepsDeferredSchemasActive(mode: boolean | DeferredToolMode): boolean {
  return mode === true || mode === "anthropic_tool_reference" || mode === "openai_codex_defer_loading";
}

export function computeActiveTools(
