  ["task", "agent"],
  ["read", "read"],
  ["edit", "edit"],
  ["write", "write"],
  ["grep", "grep"],
  ["find", "find"],
  ["ls", "ls"],
  ["webfetch", "web_fetch"],
  ["web_fetch", "web_fetch"],
  ["websearch", "web_search"],
  ["web_search", "web_search"],
]);

