// file/shell tools use upstream lowercase names; Agent and the Task* job-control
// tools keep their CC-canonical casing (no lowercase form).
const PREFERRED_TOOL_NAMES = new Map<string, string>([
  ["bash", "bash"],
  ["bash_output", "BashOutput"],
  ["bash_kill", "KillShell"],
  ["agent", "Agent"],
  ["read", "read"],
  ["edit", "edit"],
  ["write", "write"],
  ["grep", "grep"],
  ["find", "find"],
  ["ls", "ls"],
  ["web_fetch", "web_fetch"],
  ["web_search", "web_search"],
]);

