// not been pushed"). Pinning --target makes the step independent of tag-push
// ordering and lets a later run backfill Releases for already-published
// versions whose tags never made it out.
const target = process.env.GITHUB_SHA || "main";

const notesDir = mkdtempSync(join(tmpdir(), "release-notes-"));
let created = 0;
let skipped = 0;
const failures = [];
for (const { name, version } of published) {
  const tag = `${name}@${version}`;
  if (releaseExists(tag)) {
    console.log(`• ${tag} — release already exists, skipping`);
    skipped++;
    continue;
  }

  const dir = nameToDir.get(name);
  let body = "";
  const clPath = dir && join(dir, "CHANGELOG.md");
  if (clPath && existsSync(clPath)) {
    body = changelogEntry(readFileSync(clPath, "utf8"), version);
  }
  if (!body) body = `Release ${tag}.`;
  if (body.length > BODY_LIMIT) {
    body = body.slice(0, BODY_LIMIT - TRUNCATE_FOOTER.length) + TRUNCATE_FOOTER;
    console.log(`  (body truncated to ${body.length} chars)`);
  }

  // --notes-file instead of --notes: a near-BODY_LIMIT body passed as one argv
  // element can exceed the kernel's per-argument size cap (chars ≠ bytes).
  const notesFile = join(notesDir, `${created + skipped + failures.length}.md`);
  writeFileSync(notesFile, body);

  try {
    execFileSync(
      "gh",
      ["release", "create", tag, "--title", tag, "--target", target, "--notes-file", notesFile],
      { stdio: "inherit" },
    );
    console.log(`✓ ${tag} — release created`);
    created++;
  } catch (error) {
    // One bad release must not abort the rest — that is this script's whole
    // reason to exist. Record and continue; fail the job at the end.
    console.error(`✗ ${tag} — release creation failed: ${error.message}`);
    failures.push(tag);
  }
}

console.log(`Done: ${created} created, ${skipped} skipped, ${failures.length} failed.`);
if (failures.length > 0) {
  console.error(`Failed releases: ${failures.join(", ")}`);
  process.exit(1);
}

